mapper.select:
SELECT t.*, reference_name(reference_type_lk, reference_id) as reference_name
FROM tasks t
WHERE
t.record_status_lk != 'DL'

  and (
    t.task ilike '%' || #{filters.searchText} || '%'
    or t.description ilike '%' || #{filters.searchText} || '%'
  )


  and
  (

    t.create_user_id = #{userId}
    or t.assigned_user_id = #{userId}
    or t.assigned_user_group_id IN (SELECT user_group_id FROM user_group_users WHERE user_id = #{userId})
    or t.assigned_user_id IN (SELECT subordinate_user_id FROM user_subordinates WHERE user_id = #{userId})
  )

and NOT (

  t.task_status_lk not in ('COMPLETED', 'CANCELLED')
  or (t.task_status_lk = 'COMPLETED' and t.last_change_date > (now() - interval '5 days'))
)
and exists (
  SELECT * from vw_permissions vp where vp.current_user_id = #{userId} and vp.permission_lk = 'TASKS'
  and (
    vp.permission_target_lk = 'ALL'
    or (
      vp.permission_target_lk = 'OWN' and t.create_user_id = #{userId}
    ) or (
      vp.permission_target_lk = 'SUB' and t.create_user_id = vp.owner_user_id
    )
  )
)
ORDER BY t.last_change_date DESC
LIMIT #{filters.limit} OFFSET #{filters.skip}

SELECT t.*, reference_name(reference_type_lk, reference_id) as reference_name
FROM tasks t
WHERE
t.record_status_lk != 'DL'
and t.reference_type_lk = #{referenceTypeLk}
and t.reference_id = #{referenceId}
and NOT (

  t.task_status_lk not in ('COMPLETED', 'CANCELLED')
  or (t.task_status_lk = 'COMPLETED' and t.last_change_date > (now() - interval '3 days'))
)
and exists (
  SELECT * from vw_permissions vp where vp.current_user_id = #{userId} and vp.permission_lk = 'TASKS'
  and (
    vp.permission_target_lk = 'ALL'
    or (
      vp.permission_target_lk = 'OWN' and t.create_user_id = #{userId}
    ) or (
      vp.permission_target_lk = 'SUB' and t.create_user_id = vp.owner_user_id
    )
  )
)
ORDER BY t.last_change_date DESC
LIMIT #{filters.limit} OFFSET #{filters.skip}

SELECT t.*, reference_name(reference_type_lk, reference_id) as reference_name
FROM tasks t
WHERE
t.record_status_lk != 'DL'
and t.task_id = #{taskId}
and exists (
  SELECT * from vw_permissions vp where vp.current_user_id = #{userId} and vp.permission_lk = 'TASKS'
  and (
    vp.permission_target_lk = 'ALL'
    or (
      vp.permission_target_lk = 'OWN' and t.create_user_id = #{userId}
    ) or (
      vp.permission_target_lk = 'SUB' and t.create_user_id = vp.owner_user_id
    )
  )
)
